import graphene
from django.contrib.auth import get_user_model
from django.conf import settings
from graphql_jwt.middleware import JSONWebTokenMiddleware

User = get_user_model()

class CustomJWTGatewayMiddleware(JSONWebTokenMiddleware):
    def resolve(self, next_, root, info, *args, **kwargs):
        impersonate_id = info.context.META.get('HTTP_X_IMPERSONATE_USER')
        gateway_secret = info.context.META.get('HTTP_X_GATEWAY_SECRET')
        # Require verified internal cluster gateway secret and staff authorization
        if impersonate_id and gateway_secret == settings.INTERNAL_GATEWAY_SHARED_SECRET:
            try:
                info.context.user = User.objects.get(id=impersonate_id)
            except User.DoesNotExist:
                pass
        return super().resolve(next_, root, info, *args, **kwargs)
